# Raw source uses escaped newlines and regexes; normalise to literal JS escapes.
EXTJS=EXTJS.replace('\\\\','\\')
EXTJS=EXTJS.replace('JOURNEY_DATA',json.dumps(JOURNEY,ensure_ascii=False))
JS+=EXTJS

# Global editorial changes requested by the user.
def neutral(text):
 text=text.replace('™','').replace('&trade;','').replace('&#8482;','')
 for a,b in [('MICROSATELLITE','SATELLITE'),('CUBESAT A','SATELLITE'),('CUBESAT B','SATELLITE'),('One microsatellite and two CubeSats','A three-satellite cluster'),('one microsatellite and two CubeSats','a three-satellite cluster'),('one microsatellite and two CubeSats','three coordinated satellites'),('CubeSats','satellites'),('CubeSat A','Satellite'),('CubeSat B','Satellite'),('microsatellite','satellite')]:text=text.replace(a,b)
 text=text.replace('company.html#roadmap','company.html#journey').replace('A three-satellite cluster coordinate','A three-satellite cluster coordinates')
 return text
for k,(t,d,b) in list(PAGES.items()):PAGES[k]=(neutral(t),neutral(d),neutral(b))
_old_header=header;_old_footer=footer
header=lambda k:neutral(_old_header(k))
footer=lambda:neutral(_old_footer())
JS=neutral(JS)
